import { handle, body, query, pathParam, badRequest } from '../lib/http';
import { sessionForRead, sessionForWrite } from '../lib/auth';
import { listProfiles, matchProfile, profileBundle } from '../lib/profiles';
import { startSession, getSession, listMySessions, updateSummary, storeTranscript, abandonSession } from '../lib/sessions';
import { upsertResponses } from '../lib/responses';
import { computeReadiness } from '../lib/readiness';
import { submitSession } from '../lib/submit';
import { raiseFollowUp, myOpenFollowUps } from '../lib/followups';
/*
 * Thin route handlers. Each delegates to a lib module; `handle` supplies the
 * response envelope and error mapping. Ownership checks happen in
 * sessionForRead / sessionForWrite before any lib call touches a session.
 */
// ---------- Profiles ----------
/** GET /profiles?target_table= */
export function getProfiles(request, response) {
    handle(request, response, (req) => ({ result: listProfiles(query(req, 'target_table')) }));
}
/** GET /profiles/match?target_table=&context={json} */
export function getProfileMatch(request, response) {
    handle(request, response, (req) => {
        let context = {};
        const raw = query(req, 'context');
        if (raw) {
            try {
                context = JSON.parse(raw);
            }
            catch (e) {
                throw badRequest('context must be a JSON object');
            }
        }
        return { result: matchProfile(query(req, 'target_table'), context) };
    });
}
/** GET /profiles/{id} */
export function getProfile(request, response) {
    handle(request, response, (req) => ({ result: profileBundle(pathParam(req, 'id')) }));
}
// ---------- Sessions ----------
/** GET /sessions?state= — the caller's own sessions */
export function getSessions(request, response) {
    handle(request, response, (req) => ({ result: listMySessions(query(req, 'state')) }));
}
/** POST /sessions { profile_id, channel } */
export function postSession(request, response) {
    handle(request, response, (req) => ({ status: 201, result: startSession(body(req)) }));
}
/** GET /sessions/{id} — session, profile bundle, responses, readiness */
export function getSessionById(request, response) {
    handle(request, response, (req) => ({ result: getSession(sessionForRead(pathParam(req, 'id'))) }));
}
/** PATCH /sessions/{id} { summary } */
export function patchSession(request, response) {
    handle(request, response, (req) => ({
        result: updateSummary(sessionForWrite(pathParam(req, 'id')), body(req).summary),
    }));
}
/** PUT /sessions/{id}/responses { responses: [...] } — returns readiness after the write */
export function putResponses(request, response) {
    handle(request, response, (req) => {
        const s = sessionForWrite(pathParam(req, 'id'));
        const out = upsertResponses(s, body(req).responses);
        const status = out.errors.length && !out.written.length ? 400 : 200;
        return { status, result: { ...out, readiness: computeReadiness(s) } };
    });
}
/** GET /sessions/{id}/readiness */
export function getReadiness(request, response) {
    handle(request, response, (req) => ({ result: computeReadiness(sessionForRead(pathParam(req, 'id')), false) }));
}
/** POST /sessions/{id}/transcript { transcript } */
export function postTranscript(request, response) {
    handle(request, response, (req) => ({
        result: storeTranscript(sessionForWrite(pathParam(req, 'id')), body(req).transcript),
    }));
}
/** POST /sessions/{id}/submit { acknowledge_gaps? } */
export function postSubmit(request, response) {
    handle(request, response, (req) => ({ result: submitSession(sessionForWrite(pathParam(req, 'id')), body(req)) }));
}
/** POST /sessions/{id}/abandon */
export function postAbandon(request, response) {
    handle(request, response, (req) => ({ result: abandonSession(sessionForWrite(pathParam(req, 'id'))) }));
}
// ---------- Follow-ups ----------
/** GET /followups — open follow-ups addressed to the caller */
export function getFollowUps(request, response) {
    handle(request, response, () => ({ result: myOpenFollowUps() }));
}
/** POST /sessions/{id}/followups { question, criterion_id? } — reviewers only */
export function postFollowUp(request, response) {
    handle(request, response, (req) => ({
        status: 201,
        result: raiseFollowUp(sessionForRead(pathParam(req, 'id')), body(req)),
    }));
}
